using HotChocolate.Authorization;
using GraphApi.Infrastructure.Services;using GraphApi.Models.TKT.ComentariosTicket;using GraphApi.Services.TKT.ComentariosTicket;using HotChocolate;using System.Linq;namespace GraphApi.GraphQL.TKT.ComentariosTicket{    [MutationType]    [GraphQLDescription("Punto de entrada para las mutaciones de ComentariosTickets: creación, actualización y eliminación.")]    public class ComentariosTicketMutation    {        [Authorize]        [GraphQLName("createComentariosTicket")]        [GraphQLDescription("Crea un nuevo ComentariosTicket usando los headers 'UserID' y 'WindowName'.")]        public async Task<clReadComentariosTicket> CreateComentariosTicketAsync(            [GraphQLDescription("Datos necesarios para crear el ComentariosTicket.")]            clCreateComentariosTicket objInput,            [Service]            [GraphQLDescription("Servicio para operaciones de ComentariosTicket.")]            IComentariosTicketService objService,
            [Service] IGraphQLContextService objCtx        )        {            var (userId, windowName) = objCtx.GetRequestContext();            return await objService.CreateComentariosTicket(objInput, userId, windowName);        }        [Authorize]        [GraphQLName("updateComentariosTicket")]        [GraphQLDescription("Actualiza los campos especificados de un ComentariosTicket existente.")]        public async Task<clReadComentariosTicket?> UpdateComentariosTicketAsync(            [GraphQLDescription("Datos del ComentariosTicket a actualizar.")]            clUpdateComentariosTicket objInput,            [Service]            [GraphQLDescription("Servicio para operaciones de ComentariosTicket.")]            IComentariosTicketService objService,
            [Service] IGraphQLContextService objCtx        )        {            var (userId, windowName) = objCtx.GetRequestContext();            return await objService.UpdateComentariosTicket(objInput, userId, windowName);        }        [Authorize]        [GraphQLName("deleteComentariosTicket")]        [GraphQLDescription("Elimina un ComentariosTicket por su ID.")]        public async Task<bool> delComentariosTicketAsync(            [GraphQLDescription("ID del ComentariosTicket a eliminar.")]            int nComentariosTicketID,            [Service]            [GraphQLDescription("Servicio para operaciones de ComentariosTicket.")]            IComentariosTicketService objService        )        {            return await objService.DeleteComentariosTicket(nComentariosTicketID);        }    }}